import json
import argparse
import os
from pathlib import Path
from typing import Dict, List, Tuple, Optional, Any


def load_training_data_json(run_id: str) -> Dict[str, Any]:
    """Load training data from the JSON file generated by analysis."""
    json_path = os.path.join("evals", run_id, "analysis", "BoN", "training_data.json")
    try:
        with open(json_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except FileNotFoundError:
        print(f"Error: training_data.json not found at {json_path}")
        return {}
    except json.JSONDecodeError:
        print(f"Error: Could not decode JSON from {json_path}")
        return {}


def filter_by_improvement_rate(data: Dict[str, Any], threshold: float = 1.0) -> Tuple[Dict[str, Any], Dict[str, Any]]:
    """
    Filter data by improvement rate.
    Returns (filtered_data, high_improvement_data)
    """
    filtered_data = {}
    high_improvement_data = {}
    
    for key, item in data.items():
        improvement_rate = item.get("improvement_rate", 0.0)
        if improvement_rate >= threshold:
            high_improvement_data[key] = item
        else:
            filtered_data[key] = item
    
    return filtered_data, high_improvement_data


def mark_replay_items(current_data: Dict[str, Any], prev_run_id: str) -> Dict[str, Any]:
    """Mark items as replay or frontier based on previous run data."""
    prev_data = load_training_data_json(prev_run_id)
    
    # Create a set of keys that had improvement_rate <= 0 in previous run
    replay_keys = set()
    for key, item in prev_data.items():
        if item.get("improvement_rate", 0.0) <= 0:
            replay_keys.add(key)
    
    # Mark current items
    for key, item in current_data.items():
        if key in replay_keys:
            item["split"] = "replay"
        else:
            item["split"] = "frontier"
    
    return current_data


def adjust_replay_proportion(data: Dict[str, Any], high_improvement_data: Dict[str, Any], 
                           replay_buffer_split: float) -> Dict[str, Any]:
    """
    Adjust the proportion of replay items to match replay_buffer_split.
    """
    if not data:
        return data
    
    # Count current replay and frontier items
    replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
    frontier_count = sum(1 for item in data.values() if item.get("split") == "frontier")
    total_count = len(data)
    
    if total_count == 0:
        return data
    
    current_proportion = replay_count / total_count
    target_proportion = replay_buffer_split
    
    print(f"Current replay proportion: {current_proportion:.3f}, Target: {target_proportion:.3f}")
    
    if current_proportion > target_proportion:
        # Too many replay items, remove some
        replay_items = [(k, v) for k, v in data.items() if v.get("split") == "replay"]
        target_replay_count = int(total_count * target_proportion)
        items_to_remove = replay_count - target_replay_count
        
        # Remove replay items (keep the ones with higher improvement rates)
        replay_items.sort(key=lambda x: x[1].get("improvement_rate", 0.0), reverse=True)
        for i in range(items_to_remove):
            if i < len(replay_items):
                del data[replay_items[i][0]]
    
    elif current_proportion < target_proportion:
        # Too few replay items, add from high_improvement_data
        target_replay_count = int(total_count * target_proportion)
        items_to_add = target_replay_count - replay_count
        
        # Sort high_improvement_data by improvement_rate (ascending) to add lowest ones
        sorted_high_items = sorted(high_improvement_data.items(), 
                                 key=lambda x: x[1].get("improvement_rate", 0.0))
        
        for i in range(min(items_to_add, len(sorted_high_items))):
            key, item = sorted_high_items[i]
            item["split"] = "replay"
            data[key] = item
    
    return data


def create_sft_dataset(data: Dict[str, Any], thinking: bool = False) -> List[Dict[str, str]]:
    """Create SFT dataset in Alpaca format."""
    dataset = []
    
    for key, item in data.items():
        champion = item["samples"]["champion"]
        if champion["output"] is None:
            continue
        
        output_text = champion["cot_output"] if thinking else champion["output"]
        if output_text is None:
            continue
        
        dataset.append({
            "instruction": item["prompt"],
            # "input": "",
            "output": output_text
        })
    
    return dataset


from collections import defaultdict
import math

def softmax(scores, tau=1.0):
    # Compute softmax with temperature tau
    if tau == 0:
        # Avoid division by zero, treat as argmax
        max_idx = scores.index(max(scores))
        return [1.0 if i == max_idx else 0.0 for i in range(len(scores))]
    exp_scores = [math.exp(s / tau) for s in scores]
    total = sum(exp_scores)
    return [e / total for e in exp_scores]

def group_and_weight_by_key(deduped_dataset, tau=1.0):
    # Group items by key
    grouped = defaultdict(list)
    for item in deduped_dataset:
        grouped[item["key"]].append(item)
    # For each group, compute softmax weights and add to items
    for key, items in grouped.items():
        scores = [item["score"] for item in items]
        weights = softmax(scores, tau)
        for item, w in zip(items, weights):
            item["weight"] = w / len(list(grouped.keys()))
    # Flatten back to a list
    return [item for items in grouped.values() for item in items]

def create_weighted_sft_dataset(data: Dict[str, Any], thinking: bool = False, tau: float = 1.0) -> List[Dict[str, Any]]:
    """Create weighted SFT dataset with scores."""
    dataset = []
    
    for key, item in data.items():
        samples = item["samples"]
        
        # Include all samples except invalid
        for sample_name, sample in samples.items():
            if sample_name == "invalid" or sample["output"] is None:
                continue
            
            output_text = sample["cot_output"] if thinking else sample["output"]
            if output_text is None:
                continue
            
            dataset.append({
                "key" : key,
                "instruction": item["prompt"],
                # "input": "",
                "output": output_text,
                "score": sample["delta"] if sample["delta"] is not None else 0.0
            })
    # Deduplicate the dataset by output_text before returning
    seen_outputs = set()
    deduped_dataset = []
    for item in dataset:
        output_text = (item["key"],item["output"])
        if output_text not in seen_outputs:
            deduped_dataset.append(item)#{k:v for k,v in item.items() if k!="key"})
            seen_outputs.add(output_text)

    weighted_dataset_raw = group_and_weight_by_key(deduped_dataset, tau)
    
    weighted_dataset = {k:v for k,v in weighted_dataset_raw if k!="key" and k!='score'}
    
    return weighted_dataset


def create_dpo_dataset(data: Dict[str, Any], thinking: bool = False) -> List[Dict[str, str]]:
    """Create DPO preference pairs dataset."""
    dataset = []
    
    for key, item in data.items():
        samples = item["samples"]
        champion = samples["champion"]
        
        if champion["output"] is None:
            continue
        
        champion_text = champion["cot_output"] if thinking else champion["output"]
        if champion_text is None:
            continue
        
        # Create pairs with all other samples
        for sample_name, sample in samples.items():
            if sample_name == "champion" or sample["output"] is None or sample_name == "invalid" :
                continue
            
            rejected_text = sample["cot_output"] if thinking else sample["output"]
            if rejected_text is None:
                continue
            
            if sample['delta'] is not None and sample['delta'] >= champion['delta']:
                continue
            
            dataset.append({
                "key" : key,
                "instruction": item["prompt"],
                "chosen_response": champion_text,
                "rejected_response": rejected_text
            })
    
    # Deduplicate the dataset by output_text before returning
    seen_outputs = set()
    deduped_dataset = []
    for item in dataset:
        output_text = (item["key"],item["rejected_response"])
        if output_text not in seen_outputs:
            deduped_dataset.append({k:v for k,v in item.items() if k!="key"})
            seen_outputs.add(output_text)
    
    return deduped_dataset


def save_jsonl(dataset: List[Dict[str, Any]], output_path: str):
    """Save dataset to JSONL format."""
    os.makedirs(os.path.dirname(output_path), exist_ok=True)
    
    try:
        with open(output_path, 'w', encoding='utf-8') as f:
            for item in dataset:
                f.write(json.dumps(item, ensure_ascii=False) + '\n')
        print(f"Saved {len(dataset)} items to {output_path}")
    except Exception as e:
        print(f"Error saving to {output_path}: {e}")


def main(run_id: str, output_path: Optional[str] = None, thinking: bool = False, 
         filter_threshold: float = 1.0, prev_run_id: Optional[str] = None, 
         replay_buffer_split: Optional[float] = None, training_type: str = "sft", tau: float = 1.0):
    """
    Generate training dataset from analysis results.
    
    Args:
        run_id: Identifier for the run
        output_path: Output path for the JSONL file (default: evals/run_id/analysis/BoN/training_data.jsonl)
        thinking: Whether to use CoT output (default: False)
        filter_threshold: Threshold for filtering high improvement rate items (default: 1.0)
        prev_run_id: Previous run ID for replay buffer (default: None)
        replay_buffer_split: Target proportion of replay items (default: None)
        training_type: Type of training dataset (sft, weighted_sft, dpo) (default: sft)
    """
    
    # Set default output path
    if output_path is None:
        output_path = os.path.join("evals", run_id, "analysis", "BoN", "training_data.jsonl")
    
    # Load training data
    data = load_training_data_json(run_id)
    if not data:
        print("No training data found. Exiting.")
        return
    
    print(f"Loaded {len(data)} items from training data")
    
    # Filter out items with improvement_rate <= 0
    data = {k: v for k, v in data.items() if v.get("improvement_rate", 0.0) > 0}
    print(f"After filtering improvement_rate > 0: {len(data)} items")
    
    # Mark replay items if prev_run_id and replay_buffer_split are provided
    if prev_run_id and replay_buffer_split is not None:
        data = mark_replay_items(data, prev_run_id)
        replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
        frontier_count = sum(1 for item in data.values() if item.get("split") == "frontier")
        print(f"Marked items - Replay: {replay_count}, Frontier: {frontier_count}")
    
    # Filter by improvement rate threshold
    data, high_improvement_data = filter_by_improvement_rate(data, filter_threshold)
    print(f"After filtering improvement_rate < {filter_threshold}: {len(data)} items")
    print(f"High improvement items set aside: {len(high_improvement_data)} items")
    
    # Adjust replay proportion if needed
    if prev_run_id and replay_buffer_split is not None:
        data = adjust_replay_proportion(data, high_improvement_data, replay_buffer_split)
        replay_count = sum(1 for item in data.values() if item.get("split") == "replay")
        frontier_count = sum(1 for item in data.values() if item.get("split") == "frontier")
        print(f"After replay adjustment - Replay: {replay_count}, Frontier: {frontier_count}")
    
    # Create dataset based on training type
    if training_type == "sft":
        dataset = create_sft_dataset(data, thinking)
    elif training_type == "weighted_sft":
        dataset = create_weighted_sft_dataset(data, thinking, tau)
    elif training_type == "dpo":
        dataset = create_dpo_dataset(data, thinking)
    else:
        print(f"Unknown training type: {training_type}")
        return
    
    # Save dataset
    save_jsonl(dataset, output_path)


def get_parser():
    parser = argparse.ArgumentParser(description="Generate training dataset from analysis results.")
    parser.add_argument("run_id", help="Identifier for the run.")
    parser.add_argument("--output_path", default=None, help="Output path for JSONL file (default: evals/[run_id]/analysis/BoN/training_data.jsonl)")
    parser.add_argument("--thinking", action="store_true", help="Use CoT output instead of regular output (default: False)")
    parser.add_argument("--filter_threshold", type=float, default=1.0, help="Threshold for filtering high improvement rate items (default: 1.0)")
    parser.add_argument("--prev_run_id", default=None, help="Previous run ID for replay buffer (default: None)")
    parser.add_argument("--replay_buffer_split", type=float, default=None, help="Target proportion of replay items (default: None)")
    parser.add_argument("--type", choices=["sft", "weighted_sft", "dpo"], default="sft", help="Type of training dataset (default: sft)")
    parser.add_argument("--tau", default=1.0, help="temperature value for weighted SFT")
    return parser


if __name__ == "__main__":
    parser = get_parser()
    args = parser.parse_args()
    main(args.run_id, args.output_path, args.thinking, args.filter_threshold, 
         args.prev_run_id, args.replay_buffer_split, args.type)
